import{_ as a,o as n,a as p,b as l}from"./app.BGziXukh.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"api/SIMD-API/adv_api/HCCL_communication/HCCL_MC2/Mc2GetSupportAlgList.md","filePath":"api/SIMD-API/adv_api/HCCL_communication/HCCL_MC2/Mc2GetSupportAlgList.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1795402474000}'),t={name:"api/SIMD-API/adv_api/HCCL_communication/HCCL_MC2/Mc2GetSupportAlgList.md"};function c(e,s,o,d,i,r){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>Mc2GetSupportAlgList</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR&amp;950DT系列产品：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品AI Core：不支持</li><li>Atlas推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>查询当前通信域上，指定通信任务类型和通信引擎下可用的算法名单。查询结果以JSON字符串写入调用方提供的缓冲区。</p><p>使用本接口前，必须先调用<a href="Mc2GetCcArgs.html">Mc2GetCcArgs</a>创建通信参数对象，并调用<a href="Mc2SetCcCommEngine.html">Mc2SetCcCommEngine</a>设置通信引擎；如需按数据长度过滤名单，可先调用<a href="Mc2SetCcDataLenRange.html">Mc2SetCcDataLenRange</a>设置数据长度范围。</p><p>查询结果中的名字可直接作为<a href="Mc2SetCcAlgConfig.html">Mc2SetCcAlgConfig</a>的算法名参数，设置后按正常流程申请通信资源并执行通信。若已通过<a href="Mc2SetCcDataLenRange.html">Mc2SetCcDataLenRange</a>设置数据长度范围，名单按该范围过滤：算法的长度条件与该范围有重叠即列入。</p><p>本接口只做查询，不申请通信资源，也不启动通信服务端。</p><p>查询结果格式固定为三字段JSON，成功与失败通过error_msg字段是否为空区分：</p><ul><li><p>查询成功：<code>{&quot;count&quot;:N,&quot;alg_list&quot;:[&quot;算法名&quot;,...],&quot;error_msg&quot;:[]}</code>，N为算法个数。示例：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>{&quot;count&quot;:2,&quot;alg_list&quot;:[&quot;sole[mesh]&quot;,&quot;sole[nhr]&quot;],&quot;error_msg&quot;:[]}
</code></pre></div></li><li><p>查询失败：<code>{&quot;count&quot;:0,&quot;alg_list&quot;:[],&quot;error_msg&quot;:[&quot;失败原因&quot;]}</code>。示例：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>{&quot;count&quot;:0,&quot;alg_list&quot;:[],&quot;error_msg&quot;:[&quot;alg list buffer insufficient: need[2110] len[2048], recommended 16K&quot;]}
</code></pre></div></li></ul><p>参数合法但当前拓扑下没有可用算法时，属于查询成功，alg_list为空数组：<code>{&quot;count&quot;:0,&quot;alg_list&quot;:[],&quot;error_msg&quot;:[]}</code>。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">extern</span><span class="w"> </span><span class="n">Mc2Result</span><span class="w"> </span><span class="n">__attribute__</span><span class="p">((</span><span class="n">visibility</span><span class="p">(</span><span class="s">&quot;default&quot;</span><span class="p">)))</span><span class="w"> </span><span class="n">Mc2GetSupportAlgList</span><span class="p">(</span>
<span class="w">    </span><span class="n">HcclComm</span><span class="w"> </span><span class="n">comm</span><span class="p">,</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">ccType</span><span class="p">,</span><span class="w"> </span><span class="kt">void</span><span class="o">*</span><span class="w"> </span><span class="n">ccArgs</span><span class="p">,</span><span class="w"> </span><span class="kt">char</span><span class="o">*</span><span class="w"> </span><span class="n">algs</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">len</span><span class="p">)</span>
</code></pre></div><p>本接口为C链接接口（声明于<code>extern &quot;C&quot;</code>块内，符号无C++名修饰），可在C与C++宿主程序中直接调用。</p><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>comm</td><td>输入</td><td>已初始化的通信域句柄。</td></tr><tr><td>ccType</td><td>输入</td><td>通信任务类型，取值为HcclCMDType枚举值，当前支持AllGather、AllReduce、ReduceScatter、AlltoAll和AlltoAllV。</td></tr><tr><td>ccArgs</td><td>输入</td><td><a href="Mc2GetCcArgs.html">Mc2GetCcArgs</a>创建并通过Mc2SetCc*接口填充的MC2通信参数对象。</td></tr><tr><td>algs</td><td>输出</td><td>查询结果缓冲区，由调用方分配，接口写入完整JSON并以&#39;\\0&#39;结尾。建议不小于16KB。</td></tr><tr><td>len</td><td>输入</td><td>algs缓冲区大小。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>返回HcclResult类型的值，具体取值参考下表。</p><p><strong>表2</strong> 返回值说明</p><table><thead><tr><th>返回值</th><th>描述</th></tr></thead><tbody><tr><td>HCCL_SUCCESS</td><td>查询成功。</td></tr><tr><td>HCCL_E_PTR</td><td>comm或ccArgs为空指针，或algs为空指针且len大于0。</td></tr><tr><td>HCCL_E_NOT_SUPPORT</td><td>通信任务类型不支持、通信引擎不支持，或结果JSON超出缓冲区大小。</td></tr></tbody></table><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>查询成功时写入完整的结果JSON；结果超出缓冲区容量时写入完整的失败JSON（含所需的缓冲区大小），不写入截断的JSON。</li><li>缓冲区不足以容纳失败JSON时仅写入一个结束符&#39;\\0&#39;；len为0时不写入任何内容。</li><li>通信引擎仅支持<code>CCU_SCHED</code>（对应CCU路径）和<code>AICPU_TS</code>（对应AI CPU路径），其他取值（含<code>CCU_MS</code>）不支持本接口查询。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">kCcuSchedEngine</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">6U</span><span class="p">;</span><span class="w"> </span><span class="c1">// CCU_SCHED</span>
<span class="k">const</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">ccType</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">uint8_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">HcclCMDType</span><span class="o">::</span><span class="n">HCCL_CMD_ALLGATHER</span><span class="p">);</span>
<span class="kt">char</span><span class="w"> </span><span class="n">algs</span><span class="p">[</span><span class="mi">16384</span><span class="p">];</span><span class="w"> </span><span class="c1">// 建议不小于16KB</span>
<span class="c1">// ccArgs已由Mc2GetCcArgs创建，并经Mc2SetCcCommEngine(ccArgs, kCcuSchedEngine)、</span>
<span class="c1">// Mc2SetCcSrcDataType设置；可选经Mc2SetCcDataLenRange设置数据长度范围</span>

<span class="n">Mc2Result</span><span class="w"> </span><span class="n">ret</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">Mc2GetSupportAlgList</span><span class="p">(</span><span class="n">comm</span><span class="p">,</span><span class="w"> </span><span class="n">ccType</span><span class="p">,</span><span class="w"> </span><span class="n">ccArgs</span><span class="p">,</span><span class="w"> </span><span class="n">algs</span><span class="p">,</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">algs</span><span class="p">));</span>
<span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">ret</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="n">HCCL_SUCCESS</span><span class="w"> </span><span class="o">&amp;&amp;</span><span class="w"> </span><span class="n">strstr</span><span class="p">(</span><span class="n">algs</span><span class="p">,</span><span class="w"> </span><span class="s">&quot;</span><span class="se">\\&quot;</span><span class="s">error_msg</span><span class="se">\\&quot;</span><span class="s">:[]&quot;</span><span class="p">)</span><span class="w"> </span><span class="o">!=</span><span class="w"> </span><span class="nb">nullptr</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="c1">// 解析alg_list，取一个算法名经Mc2SetCcAlgConfig设置后执行</span>
<span class="w">    </span><span class="n">ret</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">Mc2SetCcAlgConfig</span><span class="p">(</span><span class="n">ccArgs</span><span class="p">,</span><span class="w"> </span><span class="s">&quot;sole[mesh]&quot;</span><span class="p">);</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">ret</span><span class="w"> </span><span class="o">!=</span><span class="w"> </span><span class="n">HCCL_SUCCESS</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="c1">// 错误处理</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const C=a(t,[["render",c]]);export{u as __pageData,C as default};
